import{d as x,C as t,o as c,c as u,j as a,a as s,E as n,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第四十九章","description":"循王弼因物、不弃人的解释，理解无常心、德善德信与歙歙孩之。","frontmatter":{"title":"道德经第四十九章","description":"循王弼因物、不弃人的解释，理解无常心、德善德信与歙歙孩之。","category":"guide","aliases":["道德经第四十九章","老子第四十九章","dao de jing chapter 49"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-49.md","filePath":"daoism/dao-de-jing/chapter-49.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-49.md"},_=x({...b,setup(p){const r=[{id:"no-fixed-private-mind",label:"圣人无常心",showLabel:!0,sentences:[["圣人无",{text:"常心",glossary:"changxin"},"，以百姓心为心。"]],note:["【白话】圣人没有固执不变的一己之心，而以百姓的心意、处境作为回应的依据。这里的无常心不是喜怒不定，而是不以自己的成见充当所有人的尺度。","【王弼注择要】「动常因也。」王弼用行动常有所因说明以百姓心为心，后文又说「天下之心不必同」，承认人心不必一样。","【读法】常心在本句取固定自守的心意。因百姓而应，不等于照单满足每一种欲望；要连后文不弃人、少以智力强制的取径理解。"]},{id:"goodness-without-abandonment",label:"善者吾善之",showLabel:!0,sentences:[[{text:"善",glossary:"shan-good"},"者吾",{text:"善",glossary:"shan-treat"},"之，不",{text:"善",glossary:"shan-good"},"者吾亦",{text:"善",glossary:"shan-treat"},"之，",{text:"德善",glossary:"deshan"},"。"]],note:["【白话】善的人，我善待他；不善的人，我也善待他。这体现不弃人的善德，让不同的人仍有被成全的可能。","【王弼注择要】「各因其用，则善不失也。」德善下注「无弃人也」，将善之连到不弃人、因其用，而非只挑选已经合意的人。","【读法】善者的善与善之的动词用法分开标词。善待不等于认可不善行为；这里也不能直接当作现代社会无需追责、无需保护受影响者的规则。"]},{id:"trust-without-exclusion",label:"信者吾信之",showLabel:!0,sentences:[[{text:"信",glossary:"xin"},"者吾",{text:"信",glossary:"xin"},"之，不",{text:"信",glossary:"xin"},"者吾亦",{text:"信",glossary:"xin"},"之，",{text:"德信",glossary:"dexin"},"。"]],note:["【白话】可信的人，我以信相待；不可信的人，我也以信相待。这体现以信待人、不先用猜忌排除人的信德。","【王弼注择要】所据此句未另见独立短注；后文长注说「以不信察物，物亦竞以不信应之」，说明一味怀疑、察制会激起相应的不信。","【读法】本页循以信待人与后文察人之弊解释德信，不把信等同于取消查证、任人欺骗。王注有以信任反省猜忌的方向，实际交往仍须辨别风险、承担责任。"]},{id:"receptivity-without-partiality",label:"歙歙焉，为天下浑其心",showLabel:!0,sentences:[["圣人在天下，",{text:"歙歙",glossary:"xixi"},"焉，为天下",{text:"浑其心",glossary:"hunxin"},"。"]],note:["【白话】圣人处在天下，收敛自己的主张，不先据定；为了天下，让自己的心不偏执于一端、不预设好恶。","【王弼注择要】「歙歙焉，心无所主也」；又说「为天下浑心焉，意无所适莫也」，以无所偏主解释歙歙、浑心。","【读法】所据正文作歙歙，未见本站的焉；浑对应录文渾。无所主不是没有判断能力，而是不以一己偏好逼人迎合。王注对察人之弊的反省，也不等于反对一切必要监督。"]},{id:"faculties-and-childlike-harmony",label:"百姓皆注其耳目",showLabel:!0,sentences:[["百姓皆",{text:"注",glossary:"zhu"},"其耳目，圣人皆",{text:"孩之",glossary:"haizhi"},"。"]],note:["【白话】百姓各自运用自己的耳目、聪明和所能；圣人使他们和而少欲，如婴儿般不被争逐牵走。这里依王弼解释，不译作所有人都盯着圣人。","【王弼注择要】百姓注耳目下注「各用聪明」；孩之下注「皆使和而无欲，如婴儿也」。长注又说「言者言其所知，行者行其所能」，说明各人可以用其所长。","【读法】孩之在这里取使之和而无欲的解释，带有古代治理的婴儿取象。现代类比可取少以偏见压人、给各有所用的空间，但不直接把成年人当作不具判断力的孩子。"]}],o=[{id:"changxin",term:"常心",sense:1},{id:"shan-good",term:"善",sense:1},{id:"shan-treat",term:"善",sense:2},{id:"deshan",term:"德善",sense:1},{id:"xin",term:"信",sense:1,context:"本章兼说可信与以信相待；德信另循后文察人之弊理解。"},{id:"dexin",term:"德信",sense:1},{id:"xixi",term:"歙歙",sense:1},{id:"hunxin",term:"浑其心",sense:1},{id:"zhu",term:"注",sense:1},{id:"haizhi",term:"孩之",sense:1}];return(g,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第四十九章",tabindex:"-1"},[s("道德经第四十九章 "),a("a",{class:"header-anchor",href:"#道德经第四十九章","aria-label":'Permalink to "道德经第四十九章"'},"​")],-1)),n(i,{title:"以百姓心为心，怎样避免以一己之心裁人",summary:"本章由无常心说到善待、信任及德善德信，最后写歙歙、浑心与孩之。王弼以动常因、不弃人、各用聪明相贯通，又长篇反省用一己智力察人、使人争相应对的弊端。",points:[{label:"先读",text:"无常心指不固执一己成见，依百姓实际回应，不是反复无常。"},{label:"再辨",text:"善待、信任不止于奖励合自己心意者；王弼以各因其用与无弃人解释。"},{label:"后看",text:"百姓注其耳目依各用聪明来读，孩之依使和而无欲如婴儿来读。"}],hint:"歙歙读 xī xī，浑读 hún；本页用歙歙整词释本章收敛无主之貌，与第三十六章单字歙分开。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),n(l,{sections:r,glossary:o}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"圣人无常心，以百姓心为心。",tone:"因人而应",guide:"不把一己成见固定为尺度，给不同人心与处境留下位置。"},{text:"善者吾善之，不善者吾亦善之，德善。",tone:"善待而不弃人",guide:"因其用而不弃人，仍须分清对人的善待与对行为的判断。"},{text:"百姓皆注其耳目，圣人皆孩之。",tone:"各有所用与和而少欲",guide:"依各用聪明与如婴儿的王注读法，辨清古代取象与现代类比。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(h,{items:o}),e[4]||(e[4]=m('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-为什么无常心仍能回应天下" tabindex="-1">象：为什么无常心仍能回应天下？ <a class="header-anchor" href="#象-为什么无常心仍能回应天下" aria-label="Permalink to &quot;象：为什么无常心仍能回应天下？&quot;">​</a></h3><p>若先把自己的成见固定下来，便只能让别人靠近这一尺度。王弼以动常因说圣人的行动，以天下之心不必同说明所应各异，回应因而不必依靠预定的同一心意。</p><h3 id="理-为什么长注反复批评以聪明察人" tabindex="-1">理：为什么长注反复批评以聪明察人？ <a class="header-anchor" href="#理-为什么长注反复批评以聪明察人" aria-label="Permalink to &quot;理：为什么长注反复批评以聪明察人？&quot;">​</a></h3><p>王弼指出，当治理者总以自己的智力、疑心去窥察，人也会用相应的办法迎合或对抗。这样看到的可能只是被迫表现，反而失去各人真实所能与所长。</p><h3 id="用-今天怎样借鉴不弃人、各用聪明" tabindex="-1">用：今天怎样借鉴不弃人、各用聪明？ <a class="header-anchor" href="#用-今天怎样借鉴不弃人、各用聪明" aria-label="Permalink to &quot;用：今天怎样借鉴不弃人、各用聪明？&quot;">​</a></h3><p>可先了解不同人的实际能力与需要，提供诚实表达、修正和承担责任的空间。古代圣人政治与现代协作并不相同，能借用的是减少偏见、让人有所用的提醒。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>把善待与行为边界一起落实。</strong> 不因一次失误就把人彻底否定，同时说清责任、改进条件与保护措施。善待若只剩无条件迁就，也难以让受影响的人得到成全。</p><p><strong>少制造必须迎合的信号。</strong> 若人们只能重复上位者期待的话，判断便会失去真实材料。让不同意见可以被说明，也让各人有机会使用自己的所长。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我是在了解别人的实际处境，还是只寻找能印证自己判断的表现？我能否同时做到不轻弃人、说清责任，并给真实意见留下位置？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文与标点沿本站保留，据卷三 010a–011b 电子录文核对；正文歙歙之后本站有焉，录文未见，浑对应渾。</li><li>德善依王注无弃人解释；德信以信相待，结合后文以不信察物的长注说明，不将没有逐句短注的地方补造为独立王注。</li><li>百姓皆注其耳目依各用聪明释读，孩之依使和而无欲如婴儿释读，不将不同常见译法混作同一注。歙歙另设本章整词，善区分善良与善待。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_003.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷三 HFL 本电子录文，010a–011b</a>。</p>',15))])}}});export{y as __pageData,_ as default};
